cssRules:
.timeline-feed {
  position: relative;
  padding-left: 20px;
}
.timeline-feed::before {
  content: '';
  position: absolute;
  left: 6px;
  top: 6px;
  bottom: 6px;
  width: 1px;
  background: #27272a;
}
.timeline-item {
  position: relative;
  padding-bottom: 16px;
}
.timeline-marker {
  position: absolute;
  left: -20px;
  top: 4px;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #09090b;
  border: 2px solid #52525b;
}
.timeline-item.done .timeline-marker {
  border-color: #22c55e;
  background: #14532d;
}
.timeline-title {
  font-size: 13px;
  font-weight: 500;
  color: #e4e4e7;
}
.timeline-time {
  font-size: 11px;
  color: #71717a;
  margin-top: 2px;
}
